 if(id==54){if(!g->itemBonuses52.scalar[B52_bNoGemStone])--*inventory_stack(g,ITEM_BLUE_GEM);int i=combat_portal_slot(g);g->portals[i]=(SkillPortal){x,y,g->time+5*rank,dest,8};combat_message(g,"Warp Portal open. Stand near it and press A to travel.");}
 else if(choice){g->travel=dest;g->travelRequest=1;combat_message(g,"Returning to home.");}
 else {g->x=x;g->y=y;g->target=-1;for(int i=0;i<MOB_COUNT;i++)g->mobs[i].aggro=0;combat_sound(g,1);combat_message(g,"Teleported to a safe location on this map.");}
